WITH CompanyMax AS (SELECT company_id, employee_id, employee_name, salary, MAX(salary) OVER (PARTITION BY company_id) AS max_sal FROM Salaries) SELECT company_id, employee_id, employee_name, ROUND(salary * (1 - CASE WHEN max_sal < 1000 THEN 0.00 WHEN max_sal <= 10000 THEN 0.24 ELSE 0.49 END)) AS salary FROM CompanyMax;
